  const MONEY = new Set(['fee', 'bal', 'amt', 'ask', 'max', 'cost', 'saved', 'debt', 'wsum', 'pp', 'pw', 'pd', 'pq', 'ps', 'pf', 'px', 'cost']);
  let cur = 'en';

  SF.I18N = {
    LANGS, D,
    set(l) { cur = IDX[l] != null ? l : 'en'; },
    get() { return cur; },
    t(key, p) {
      const e = D[key];
      let s = e ? e[IDX[cur]] || e[0] : key;
      if (p) s = s.replace(/\{(\w+)\}/g, (m, k) => (k in p ? (MONEY.has(k) && typeof p[k] === 'number' ? SF.util.money(p[k]) : p[k]) : m));
      return s;
    },
  };
